export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] || key);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };

  const step = String(inputs.sessionStep === undefined || inputs.sessionStep === null ? '' : inputs.sessionStep);
  const text = String(inputs.text === undefined || inputs.text === null ? '' : inputs.text).trim();
  const scenario = String(inputs.sessionScenario === undefined || inputs.sessionScenario === null ? '' : inputs.sessionScenario);
  let draft = {};
  try { draft = JSON.parse(String(inputs.sessionDraft === undefined || inputs.sessionDraft === null ? '{}' : inputs.sessionDraft)); } catch (e) { draft = {}; }

  const TZ_OFFSET_MIN = 5 * 60;
  const parseTashkent = (s) => {
    const m = /^([0-3]?\d)\.([01]?\d)\.(\d{4})\s+([0-2]?\d):([0-5]\d)$/.exec(s);
    if (!m) return null;
    const day = Number(m[1]), month = Number(m[2]), year = Number(m[3]), hour = Number(m[4]), minute = Number(m[5]);
    if (month < 1 || month > 12 || day < 1 || day > 31 || hour > 23) return null;
    const ms = Date.UTC(year, month - 1, day, hour, minute - TZ_OFFSET_MIN);
    if (!isFinite(ms)) return null;
    return new Date(ms);
  };

  let outcome = 'error';
  let errorText = '';
  let nextStep = '';
  let nextPrompt = '';

  if (step === 'title') {
    if (text.length < 2 || text.length > 200) { errorText = t('wizard.err.title_length'); }
    else { draft.title = text; nextStep = 'description'; nextPrompt = t('wizard.ask.description'); outcome = 'next'; }
  } else if (step === 'description') {
    draft.description = (text === '-') ? '' : text;
    nextStep = 'photo'; nextPrompt = t('wizard.ask.photo');
    outcome = 'next';
  } else if (step === 'address') {
    if (text.length < 2 || text.length > 300) { errorText = t('wizard.err.address_length'); }
    else { draft.address = text; nextStep = 'geo'; nextPrompt = t('wizard.ask.geo'); outcome = 'next'; }
  } else if (step === 'starts_at' || step === 'ends_at' || step === 'reg_deadline_at') {
    const d = parseTashkent(text);
    const now = Date.now();
    if (!d) {
      errorText = t('wizard.err.datetime');
    } else if (step === 'starts_at') {
      if (d.getTime() <= now) { errorText = t('wizard.err.starts_at_past'); }
      else { draft.starts_at = d.toISOString(); nextStep = 'ends_at'; nextPrompt = t('wizard.ask.ends_at') + ' ' + t('wizard.hint.datetime'); outcome = 'next'; }
    } else if (step === 'ends_at') {
      const startsMs = draft.starts_at ? Date.parse(draft.starts_at) : NaN;
      if (isFinite(startsMs) && d.getTime() <= startsMs) { errorText = t('wizard.err.ends_before_starts'); }
      else { draft.ends_at = d.toISOString(); nextStep = 'reg_deadline_at'; nextPrompt = t('wizard.ask.reg_deadline_at') + ' ' + t('wizard.hint.datetime'); outcome = 'next'; }
    } else {
      const startsMs = draft.starts_at ? Date.parse(draft.starts_at) : NaN;
      if (d.getTime() <= now) { errorText = t('wizard.err.deadline_past'); }
      else if (isFinite(startsMs) && d.getTime() > startsMs) { errorText = t('wizard.err.deadline_after_starts'); }
      else { draft.reg_deadline_at = d.toISOString(); nextStep = 'preview'; outcome = 'preview'; }
    }
  } else {
    errorText = t('wizard.err.unexpected_step');
  }

  let previewText = '';
  if (outcome === 'preview') {
    const TZ = 'Asia/Tashkent';
    const fmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
    const f = (iso) => { if (!iso) return ''; const d2 = new Date(iso); return isNaN(d2.getTime()) ? '' : fmt.format(d2); };
    const lines = [];
    lines.push(draft.title || '');
    if (draft.description) lines.push(draft.description);
    lines.push(t('event.card.when', { when: f(draft.starts_at) }));
    lines.push(t('event.card.ends', { when: f(draft.ends_at) }));
    lines.push(t('event.card.where', { address: draft.address || '' }));
    lines.push(t('event.card.deadline', { when: f(draft.reg_deadline_at) }));
    if (draft.lat && draft.lon) lines.push(t('wizard.preview.geo', { lat: draft.lat, lon: draft.lon }));
    lines.push(draft.photo_file_id ? t('wizard.preview.photo_yes') : t('wizard.preview.photo_no'));
    previewText = t('wizard.preview.header') + '\n\n' + lines.join('\n') + '\n\n' + t('wizard.preview.confirm');
  }

  return {
    outcome: outcome, errorText: errorText, scenario: scenario,
    draft: JSON.stringify(draft), nextStep: nextStep, nextPrompt: nextPrompt,
    previewText: previewText, now: new Date().toISOString()
  };
};
